# Let's break down which specific triggers cause which predictions
test_imgs = []
labels = []
for base_idx, base in enumerate(base_imgs):
    for corner in corners:
        for pattern in patterns:
            for size in sizes:
                test_imgs.append(create_triggered_image(base, corner, pattern, size))
                labels.append((base_idx, corner, pattern, size))

test_imgs = torch.stack(test_imgs)
logits = forward(W, test_imgs)
preds = logits.argmax(dim=1)

# Analyze by trigger type
for corner in corners:
    for pattern in patterns:
        for size in sizes:
            mask = [(l[1] == corner and l[2] == pattern and l[3] == size) for l in labels]
            if sum(mask) > 0:
                subset_preds = preds[mask]
                unique, counts = subset_preds.unique(return_counts=True)
                print(f"Corner={corner}, Pattern={pattern}, Size={size}: ", end="")
                for u, c in zip(unique.tolist(), counts.tolist()):
                    print(f"Class {u}({c}) ", end="")
                print()
